import {money,resolveLines,quote,simulate,states} from './commerce.mjs';
import {createRetailSales} from './sales.mjs';
import {createAvery,averyStorefront} from './avery.mjs';
import {createDemoWorkbench} from './workbench.mjs';
import {standardOffer} from './standard-offer.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={pack:null,owner:false,staff:false,offline:false,current:'',view:location.pathname.endsWith('/pricing')?'pricing':location.pathname.endsWith('/assistant')?'assistant':'store',category:'All',search:'',presentation:false,staffData:null,staffTab:'overview',role:'owner',modal:null,rate:null,service:'pickup',destination:{zip:'28604',state:'NC'},customer:'',redeem:false,requestKey:null,research:null};
const app=$('#app');let sales,avery,workbench;let focusBeforeModal, toastTimer, cartQueue=Promise.resolve();
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('This device could not save locally. Keep the app open and free some storage.');}}
function merchant(){return state.pack.vendors.find(v=>v.slug===state.current);}
function cart(v=merchant()){return read('retail-cart-'+v.slug,[]);}
function localData(v=merchant()){return read('retail-sample-'+v.slug,{customers:[{id:'sample-1',name:'Avery Morgan',email:'avery@example.invalid',points:150,notes:[],reward_entries:[]},{id:'sample-2',name:'Jordan Lee',email:'jordan@example.invalid',points:75,notes:[],reward_entries:[]}],orders:[],stock:{},inquiries:[]});}
function voiceSample(slug){if(slug==='avery-knifeworks')return null;const v=state.pack.vendors.find(v=>v.slug===slug);if(!v||(!state.offline&&state.staff&&!v.read_only_source))return null;const d=localData(v);return{merchant:slug,customers:d.customers.filter(c=>['sample-1','sample-2'].includes(c.id)).slice(0,2).map(c=>({id:c.id,points:c.points,notes:(c.notes??[]).slice(-6).map(n=>String(n.body).slice(0,1000)),reward_entries:(c.reward_entries??[]).filter(e=>e.is_demo===true).slice(-20).map(e=>({order_id:e.order_id,earned:e.earned,redeemed:e.redeemed,is_demo:true}))})),orders:d.orders.filter(o=>o.is_demo===true&&o.status==='simulated').slice(0,30).map(o=>Object.fromEntries(['id','is_demo','status','customer_id','lines','subtotal_cents','shipping_cents','reward_credit_cents','total_cents','service','created_at'].map(k=>[k,o[k]]))) };}
function localMerchant(v=merchant()){if(!localMode())return v;const data=localData(v);return{...v,products:v.products.map(p=>({...p,variants:p.variants.map(x=>({...x,stock:data.stock[p.id+':'+x.id]??x.stock}))}))};}
function localMode(){return state.offline||!state.staff||merchant()?.read_only_source;}
async function api(path,method='GET',data=null,headers={}){const csrf=$('meta[name="csrf-token"]')?.content??'';let response;const controller=new AbortController(),timer=method==='GET'&&path.startsWith('bootstrap')?setTimeout(()=>controller.abort(),4000):null;try{response=await fetch('/retail/showroom/api/'+path,{method,signal:controller.signal,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf,...headers},body:data===null?undefined:JSON.stringify(data)});}catch(cause){const error=Error('The live connection is unavailable. Use your saved offline showroom.');error.offline=true;throw error;}finally{if(timer)clearTimeout(timer);}const result=await response.json().catch(()=>({message:'The server returned an unexpected response.'}));if(!response.ok)throw Error(result.message??Object.values(result.errors??{}).flat().join(' ')??'Request failed.');return result;}
function baseHeader(){return `<div class="notice">${state.offline?'<strong class="offline-disclosure">Offline sample</strong> · ':''}${['pricing','assistant'].includes(state.view)?'Everbranch Retail sales demonstration. Storefront activity is simulated; activation requests are reviewed separately.':'Independent demo concept by Evergrove. Not the official store. Product prices and orders are for demonstration only.'}</div><header class="appbar"><a href="/retail/showroom" class="brand" data-action="home"><img src="/retail/assets/icon.svg" alt="">Everbranch <span class="muted">Retail</span></a><div class="right"><span class="connection">${state.offline?'Offline · sample data':'Private demonstration'}</span>${state.pack.vendors.length>1?`<select id="merchant-switch" aria-label="Switch business"><option value="">All businesses</option>${state.pack.vendors.map(v=>`<option value="${esc(v.slug)}" ${state.current===v.slug?'selected':''}>${esc(v.name)}</option>`).join('')}</select>`:''}<button class="button light small" data-sales-action="voice">Talk with AI</button><button class="button light small" data-action="assistant">AI assistant</button><button class="button light small" data-action="pricing">Pricing & what’s included</button><button class="button light small" data-action="presentation">${state.presentation?'Exit presentation':'Present'}</button>${state.owner?'<button class="button light small owner-only" data-action="kit">App kit</button>':''}</div></header>`;}
function render(){state.pack.vendors=state.pack.vendors.map(averyStorefront);if(state.offline||state.pack?.offer?.key!=='standard')state.pack.offer=standardOffer;document.body.classList.toggle('presentation',state.presentation);const v=merchant();document.documentElement.style.setProperty('--ink',v?.colors.ink??'#183529');document.documentElement.style.setProperty('--accent',v?.colors.accent??'#6d824b');document.documentElement.style.setProperty('--paper',v?.colors.paper??'#f2f2e9');document.title=v?`${v.name} · Evergrove concept`:'Everbranch Retail · Private showroom';app.innerHTML=baseHeader()+(state.view==='pricing'?pricingPage():state.view==='assistant'?sales.assistantPage():v?storefront(v):showroom());}
function showroom(){const festival=state.pack.vendors.filter(v=>v.slug!=='sawyer-naturals'),sawyer=state.pack.vendors.find(v=>v.slug==='sawyer-naturals');return `<main class="wrap"><section class="showroom-intro"><div><div class="eyebrow">EVERGROVE · WOOLLY WORM SHOWROOM</div><h1>Great Businesses.<br>Your next chapter</h1><p>${festival.length} different businesses. ${festival.length} thoughtful shopping experiences. One connected way to keep the customer, the sale, and what comes next together.</p><div class="intro-actions"><button class="button" data-action="offline">${read('retail-offline-pack',null)?'Refresh offline demos':'Prepare offline demos'}</button>${state.owner?'<button class="button light owner-only" data-action="research-list">Visit & follow up</button><a class="button light owner-only" href="/retail/showroom/outreach">Review outreach</a>':''}</div></div><div class="intro-stat"><span class="eyebrow">READY TO EXPLORE</span><strong>${String(festival.length).padStart(2,'0')}</strong><p>Original storefront concepts, working carts, and shipping demonstrations. Nothing here places a real order.</p><span class="pill"><i class="dot"></i> ${state.offline?'Saved sample experiences':'Private preview · October 2026'}</span></div></section><section class="sales-intro"><div><span class="eyebrow">A BUSINESS TOOL YOU CAN TRY</span><h2>See the work. Meet your assistant.</h2><p>Explore a storefront, try the customer tools, and discover the standard offer.</p></div><div class="intro-actions"><button class="button light" data-action="assistant">Meet your AI business assistant →</button><button class="button" data-sales-action="signup">Get Started →</button></div></section><div class="section-head"><h2>Find their next chapter.</h2><span class="pill">${festival.length} festival concepts</span></div><section class="vendor-grid" aria-label="Business concepts">${festival.map(v=>`<article class="vendor-card"><div class="vendor-photo"><img src="/retail/assets/${v.image}.webp" alt="Original illustrative ${esc(categoryLabel(v))} photograph" loading="lazy"><span class="pill">${esc(v.booth)}</span></div><div class="vendor-info"><div class="eyebrow">${esc(categoryLabel(v))}</div><h3>${esc(v.name)}</h3><p>${esc(v.tagline)}</p><div class="catalog-count"><span>${v.products.length} demo products</span><span>${v.shipping.kind==='meat'?'Pickup-first':'Cart & shipping demo'}</span></div><button class="button" data-action="open" data-slug="${v.slug}">Open concept <span aria-hidden="true">↗</span></button></div></article>`).join('')}</section>${sawyer?`<section class="sawyer"><div><span class="eyebrow">ALREADY IN EVERBRANCH</span><h3>Sawyer Naturals</h3><p class="compact-info" style="margin:0">${sawyer.products.length} source-catalog products retained. Private demonstration; merchant activation remains pending.</p></div><button class="button light" data-action="open" data-slug="sawyer-naturals">Open existing demo ↗</button></section>`:''}<footer class="footer"><span>Built with care by Evergrove. Powered by Everbranch.</span><button class="text-button" data-action="clear-offline">Remove offline pack from this device</button></footer></main>`;}
function pricingPage(){return sales.pricingPage();}
function showSalesView(view){closeModal();state.view=view;if(state.owner)history.pushState({},'','/retail/showroom/'+view);render();window.scrollTo(0,0);}
function storefront(v){const count=cart(v).reduce((n,l)=>n+l.quantity,0);return `<main class="store store-${v.theme}"><div class="store-nav"><div class="merchant-name">${esc(v.name)}</div><nav><button data-action="shop">Shop</button><button class="nav-story" data-action="story">Our story</button>${v.image==='fudge'?'<button data-action="assortment">Build a box</button>':''}${v.image==='pantry'?'<button data-action="subscription">Reorder & subscribe</button>':''}${state.staff||state.offline?'<button data-action="staff">Staff workspace</button>':''}<button class="bag" data-action="cart">Bag (${count})</button></nav></div><section class="hero"><img src="${v.slug==='avery-knifeworks'?v.products[0].image:'/retail/assets/'+v.image+'.webp'}" alt="${v.slug==='avery-knifeworks'?'Avery public catalog knife photograph':'Original illustrative category photography'}"><div class="hero-copy"><div class="eyebrow">${esc(v.tagline)}</div><h1>${esc(v.headline)}</h1><p>${esc(heroCopy(v))}</p><button class="button" data-action="shop">${esc(v.cta)} <span aria-hidden="true">→</span></button></div><span class="image-credit">${v.slug==='avery-knifeworks'?'Avery catalog photograph · independent concept':'Illustrative photography · independent concept'}</span></section><div class="wrap"><div class="benefits"><span>${v.shipping.kind==='meat'?'Pickup & local delivery demo':'Thoughtfully chosen collections'}</span><span>${v.shipping.kind==='wood'||v.shipping.kind==='leather'?'One-of-a-kind inventory demo':'Easy-to-explore product choices'}</span><span>Connected customer care</span></div>${v.slug==='avery-knifeworks'?avery.launcher():''}<section class="store-content" id="catalog"><div class="section-head"><div><div class="eyebrow">${v.image==='pantry'?'FILL YOUR SHELVES':'THE COLLECTION'}</div><h2>${esc(collectionHeading(v))}</h2></div><span class="badge-sample">Private concept · demo inventory</span></div>${v.shopping_journey?`<div class="shopping-journey"><span class="eyebrow">EXPLORE YOUR WAY</span><p>${esc(v.shopping_journey)}</p></div>`:''}<div class="catalog-tools"><input id="product-search" type="search" placeholder="Search the collection…" aria-label="Search products" value="${esc(state.search)}"><div class="categories">${['All',...new Set(v.products.map(p=>p.category))].map(c=>`<button class="category ${state.category===c?'active':''}" data-action="category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div></div><div class="products" id="products">${productCards(v)}</div><section class="store-story" id="story"><img src="/retail/assets/${v.image}.webp" alt="Illustrative ${esc(v.name)} category scene" loading="lazy"><div class="story-copy"><div class="eyebrow">A CONCEPT FOR ${esc(v.name)}</div><h2>${esc(v.tagline)}</h2><p>${esc(v.shipping_profile??heroCopy(v))}</p><p class="compact-info">An independently designed demonstration. Product imagery, stock, sample options and unverified prices illustrate what a connected shopping experience could look like.</p><button class="button light" data-action="inquiry">${v.shipping.kind==='wood'?'Discuss a custom piece':v.shipping.kind==='meat'?'Ask about pickup':'Ask about gifts & custom orders'}</button></div></section><div class="policy-box" style="margin-top:25px"><strong>${v.shipping.kind==='meat'?'Pickup comes first.':'Shipping that fits the order.'}</strong>${esc(v.shipping.kind==='meat'?'Refrigerated consumer shipping remains disabled. Explore sample pickup and local delivery; no reservation or delivery is booked.':'Try changing quantities, product types and delivery ZIP in the bag. Packing rules change the sample estimate. Product measurements and merchant policies need verification before live shipping.')}</div></section><footer class="footer"><span>${esc(v.name)} · Independent Evergrove concept</span>${state.presentation&&v.slug==='avery-knifeworks'?'<button class="button" data-avery-action="handoff">Finish presentation: agreement & setup →</button>':''}<button class="text-button" data-action="home">Back to the showroom</button></footer></div></main>`;}
function categoryLabel(v){return v.category_label??({fudge:'CONFECTIONERY',farm:'FARM & PICKUP',wood:'ARTISAN WOODWORK',leather:'LEATHER GOODS',pottery:'HANDMADE CERAMICS',croft:'CANDLES · TEA · GIFTS',pantry:'PANTRY & PROVISIONS',tea:'TEA & EVERYDAY RITUALS',forge:'HAND-FORGED METALWORK',art:'ART & PRINTS',sauce:'SAUCES & SEASONINGS',beads:'JEWELRY & BEADWORK',textiles:'TEXTILES & HANDMADE GOODS'})[v.image]??'THE MAKER’S COLLECTION';}
function collectionHeading(v){return({wood:'A piece that feels like yours.',pottery:'Made for the moments between.',fudge:'Find a little happiness.',tea:'A good cup starts here.',forge:'Crafted in fire. Made for life.',art:'Find a piece that speaks to you.',sauce:'A little heat. A lot of flavor.',beads:'Find your everyday favorite.',textiles:'Color and comfort, made by hand.'})[v.image]??'Thoughtful things, worth finding.';}
function heroCopy(v){return v.intro??({fudge:'A favorite flavor. A generous gift. A small moment that makes someone’s day.',farm:'Explore a simpler way to reserve your next farm pickup and keep the details together.',wood:'Natural grain, unexpected color, and pieces with a story all their own.',leather:'Explore bags and travel companions with a considered eye for texture, form and everyday use.',pottery:'Comforting shapes and beautiful glazes, ready to become part of the everyday.',croft:'Candlelight, a warm cup, and a few lovely things that make a house feel like home.',pantry:'Find your soup-night favorites, explore pantry staples, and bring the next good meal a little closer.'})[v.image]??'Explore a thoughtful collection and a simpler way to shop.';}
function productCards(v){let products=localMerchant(v).products.filter(p=>(state.category==='All'||p.category===state.category)&&(`${p.name} ${p.category}`).toLowerCase().includes(state.search.toLowerCase()));if(!products.length)return '<div class="empty">No matching products. Try another category or search.</div>';return products.map((p,i)=>{const x=p.variants[0],stock=p.variants.some(x=>x.stock>0);return `<article class="product-card"><div class="product-photo" role="button" tabindex="0" data-action="product" data-product="${p.id}" aria-label="View ${esc(p.name)}"><img src="${esc(p.image??'/retail/assets/'+v.image+'.webp')}" alt="${p.image?'Source catalog photo':'Illustrative category photograph'} · ${esc(p.name)}" loading="lazy" style="object-position:${65+i%3*8}% ${40+i%3*15}%"><span class="sample">${p.image?'SOURCE CATALOG IMAGE':'ILLUSTRATIVE IMAGE'}${p.identity_verified?'':' · SAMPLE PRODUCT'}</span></div><div class="product-info"><span class="eyebrow" style="font-size:.6rem">${esc(p.category)}</span><h3>${esc(p.name)}</h3><div class="price">${p.quote_only?'Custom quote':money(x.price_cents)} <small>${p.price_verified?'source-observed':'example price'}</small></div><div class="product-actions">${p.variants.length>1?`<select aria-label="Choose ${esc(p.name)} option" id="variant-${p.id}">${p.variants.map(x=>`<option value="${x.id}" ${x.stock===0?'disabled':''}>${esc(x.title)} · ${money(x.price_cents)}</option>`).join('')}</select>`:`<small class="muted">${stock?(v.shipping.kind==='wood'||v.shipping.kind==='leather'?'One sample piece':'Sample stock available'):'Sample sold-out state'}</small>`}<button class="button light small" data-action="${p.quote_only?'inquiry':'add'}" data-product="${p.id}" ${!stock&&!p.quote_only?'disabled':''}>${p.quote_only?'Ask for a quote':stock?'Add to bag':'Sold out'}</button></div></div></article>`;}).join('');}
function navigate(slug,push=true){closeModal();state.view='store';state.current=slug;state.category='All';state.search='';state.staffData=null;state.rate=null;state.requestKey=null;if(push&&(state.owner||state.offline))history.pushState({},'',slug?'/retail/showroom/concepts/'+slug:'/retail/showroom');render();window.scrollTo(0,0);}
function openModal(title,body,wide=false){focusBeforeModal=document.activeElement;closeModal(false);const node=document.createElement('div');node.className='modal-backdrop';node.id='modal';node.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div id="modal-body">${body}</div></section>`;document.body.append(node);document.body.style.overflow='hidden';node.querySelector('button,input,select,textarea')?.focus();}
function closeModal(restore=true){sales?.clear();$('#modal')?.remove();document.body.style.overflow='';state.modal=null;if(restore)focusBeforeModal?.focus();}
function productDetail(id){const v=localMerchant(),p=v.products.find(p=>p.id===id);if(!p)return;openModal(p.name,`<div class="detail-grid"><div><img src="${esc(p.image??'/retail/assets/'+v.image+'.webp')}" alt="${p.image?'Source-catalog':'Illustrative'} image"><p class="compact-info">${p.image?'Existing source-catalog asset.':'Original illustrative photography; not a photo of this merchant’s actual product.'}</p></div><div><div class="eyebrow">${esc(p.category)}</div><p>${esc(p.description)}</p><div class="price">${p.quote_only?'Custom quote':money(p.variants[0].price_cents)}</div><p class="compact-info">${esc(p.price_note)}</p><label>Choose an option<select id="detail-variant">${p.variants.map(x=>`<option value="${x.id}" ${x.stock===0?'disabled':''}>${esc(x.title)} · ${money(x.price_cents)}${x.stock===0?' · sold out':''}</option>`).join('')}</select></label><button class="button" data-action="${p.quote_only?'inquiry':'add'}" data-product="${p.id}" data-detail="true" ${p.variants.every(x=>x.stock===0)?'disabled':''}>${p.quote_only?'Request a custom quote':'Add to bag'}</button><div class="policy-box"><strong>Before this becomes a real shop</strong>Inventory, packed weights, policies, image rights and merchant approval must be confirmed. ${p.oversized?'This piece requires a manual oversized shipping quote.':''}</div></div></div>`);}
async function updateCart(lines){const v=merchant();save('retail-cart-'+v.slug,lines);state.rate=null;state.requestKey=null;if(!localMode()){const snapshot=JSON.parse(JSON.stringify(lines));cartQueue=cartQueue.catch(()=>{}).then(()=>api(v.slug+'/cart','PUT',{lines:snapshot}));cartQueue.catch(e=>toast('Cart kept on this device; server save failed: '+e.message));}render();}
async function add(id,variantId=null){const v=localMerchant(),p=v.products.find(p=>p.id===id);if(!p)return;const selected=variantId??($('#detail-variant')?.value||$('#variant-'+id)?.value||p.variants[0].id),variant=p.variants.find(x=>x.id===selected);if(!variant||!variant.stock)return toast('This sample option is sold out.');const lines=cart(),existing=lines.find(l=>l.product_id===id&&l.variant_id===selected);if((existing?.quantity??0)+1>Math.min(20,variant.stock))return toast('That is the available sample stock.');if(existing)existing.quantity++;else lines.push({product_id:id,variant_id:selected,quantity:1});await updateCart(lines);closeModal();toast(p.name+' added to your bag.');}
function cartBody(){const v=localMerchant();let lines;try{lines=resolveLines(v,cart());}catch(e){return `<div class="error">${esc(e.message)}</div><button class="button light" data-action="empty-cart">Clear this sample cart</button>`;}if(!lines.length)return '<div class="empty"><h3>Your bag is waiting.</h3><p>Choose something from the collection to try the checkout.</p><button class="button" data-action="close">Keep exploring</button></div>';const subtotal=lines.reduce((s,l)=>s+l.line_cents,0);const q=state.rate,rate=q?.options.find(x=>x.id===state.service),credit=state.redeem?Math.min(500,subtotal):0;return `<div class="cart-grid"><div>${lines.map(l=>`<div class="cart-line"><div><h3>${esc(l.product.name)}</h3><small>${esc(l.variant.title)} · ${money(l.variant.price_cents)} each</small><button class="text-button" data-action="remove" data-product="${l.product.id}" data-variant="${l.variant.id}">Remove</button></div><input type="number" min="1" max="${Math.min(20,l.variant.stock)}" value="${l.quantity}" aria-label="Quantity for ${esc(l.product.name)}" data-quantity="${l.product.id}" data-variant="${l.variant.id}"><strong>${money(l.line_cents)}</strong></div>`).join('')}<div class="totals"><div class="total-row"><span>Items subtotal</span><span>${money(subtotal)}</span></div><div class="total-row"><span>Sample shipping</span><span>${rate?money(rate.amount_cents):'Choose a method'}</span></div><div class="total-row"><span>Demo reward</span><span>−${money(credit)}</span></div><div class="total-row"><span>Tax</span><span>Not calculated</span></div><div class="total-row grand"><span>Estimated total, before tax</span><span>${money(subtotal+(rate?.amount_cents??0)-credit)}</span></div></div><p class="compact-info">No payment details are collected. This creates a simulated order only.</p></div><section class="checkout-panel"><div class="eyebrow">FULFILLMENT DEMO</div><h3>Where would it go?</h3><div class="two-fields"><label>ZIP code<input id="shipping-zip" inputmode="numeric" maxlength="5" value="${esc(state.destination.zip)}" autocomplete="off"></label><label>State<select id="shipping-state">${states.map(s=>`<option ${state.destination.state===s?'selected':''}>${s}</option>`).join('')}</select></label></div><button class="button light" style="width:100%;margin-top:9px" data-action="rates">Calculate sample options</button>${q?`<div class="packing">${esc(q.reason)}</div>${q.options.map(r=>`<label class="rate"><input type="radio" name="shipping-service" value="${r.id}" ${state.service===r.id?'checked':''}><span>${esc(r.label)}<small>${esc(r.description)}</small></span><strong>${money(r.amount_cents)}</strong></label>`).join('')}<div class="packing">${q.package_groups.map(p=>`${esc(p.kind)}: ${p.weight_oz} oz · ${p.length} × ${p.width} × ${p.height} in · sample dimensions`).join('<br>')}</div>`:''}${state.staffData?`<label>Sample customer<select id="checkout-customer"><option value="">Guest demonstration</option>${state.staffData.customers.map(c=>`<option value="${c.id}" ${String(state.customer)===String(c.id)?'selected':''}>${esc(c.name)} · ${c.points} points</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" id="redeem-reward" ${state.redeem?'checked':''}> Redeem 100 demo points for $5</label>`:'<button class="text-button" data-action="checkout-customers">Add a sample customer & rewards</button>'}<button class="button" style="width:100%;margin-top:18px" data-action="checkout" ${!q?'disabled':''}>Simulate ${state.service==='pickup'?'pickup reservation':'order'} →</button></section></div>`;}
function openCart(){openModal('Your bag',cartBody(),true);state.modal='cart';}
async function calculateRates(){state.destination={zip:$('#shipping-zip').value.trim(),state:$('#shipping-state').value};try{const payload={lines:cart(),destination:state.destination};state.rate=state.offline||merchant().read_only_source?quote(localMerchant(),payload.lines,payload.destination):await api(merchant().slug+'/quote','POST',payload);if(!state.rate.options.some(r=>r.id===state.service))state.service='pickup';openCart();}catch(e){toast(e.message);}}
async function checkout(){const v=merchant();try{const lines=cart(),customer=state.staffData?.customers.find(c=>String(c.id)===String(state.customer));let order;if(localMode()){order=simulate(localMerchant(),lines,state.destination,state.service,customer,state.redeem);const data=localData();for(const l of lines){const p=localMerchant().products.find(p=>p.id===l.product_id),x=p.variants.find(x=>x.id===l.variant_id);data.stock[p.id+':'+x.id]=x.stock-l.quantity;}if(customer){const c=data.customers.find(c=>String(c.id)===String(customer.id));if(c){const earned=Math.floor((order.subtotal_cents-order.reward_credit_cents)/100);c.points+=earned-(state.redeem?100:0);c.reward_entries.push({order_id:order.id,earned,redeemed:state.redeem?100:0,is_demo:true});}}data.orders.unshift(order);save('retail-sample-'+v.slug,data);}else{await cartQueue;state.requestKey??=crypto.randomUUID();order=(await api(v.slug+'/checkout','POST',{lines,destination:state.destination,service:state.service,customer_id:customer?.id??null,redeem_points:state.redeem?100:0},{'Idempotency-Key':state.requestKey})).order;const fresh=await api('bootstrap?merchant='+v.slug);state.pack.vendors=state.pack.vendors.map(x=>x.slug===v.slug?fresh.vendors.find(y=>y.slug===v.slug):x);}
 save('retail-cart-'+v.slug,[]);state.rate=null;state.requestKey=null;state.redeem=false;state.staffData=null;render();openModal('A good next step, demonstrated.',`<div class="order-success"><div class="tick">✓</div><div class="eyebrow">SIMULATED CONFIRMATION</div><h2>${esc(order.id)}</h2><p>No purchase was made. No payment, reservation, message, delivery, or shipping label was created.</p><div class="policy-box"><strong>${esc(v.name)}</strong>${esc(order.service)}<br>${order.lines.map(l=>`${esc(l.name)} × ${l.quantity}`).join('<br>')}<hr>Estimated total before tax: ${money(order.total_cents)}${order.reward_credit_cents?'<br>Demo reward applied: '+money(order.reward_credit_cents):''}</div><div class="form-actions" style="justify-content:center">${state.staff||state.offline?'<button class="button" data-action="staff">See the staff side</button>':''}<button class="button light" data-action="close">Keep exploring</button></div></div>`);}catch(e){toast('The sample order was not confirmed: '+e.message);}}
async function loadStaff(){try{state.staffData=localMode()?{...localData(),role:state.role,user:'Sample '+state.role}:await api(merchant().slug+'/staff');return state.staffData;}catch(e){toast(e.message);return null;}}
async function openStaff(tab='overview'){if(!await loadStaff())return;state.staffTab=tab;renderStaff();}
function renderStaff(){const v=merchant(),d=state.staffData;const sales=d.orders.reduce((s,o)=>s+o.total_cents,0);let body='';
 if(state.staffTab==='overview')body=`<div class="metrics"><div class="metric"><small>Simulated receipts</small><strong>${money(sales)}</strong><small>Not real revenue</small></div><div class="metric"><small>Sample orders</small><strong>${d.orders.length}</strong><small>Nothing dispatched</small></div><div class="metric"><small>Sample customers</small><strong>${d.customers.length}</strong><small>Fictional profiles</small></div></div><h3>Take the next in-person sale.</h3><p class="compact-info">Choose a product, attach a customer, and demonstrate checkout and rewards. No card reader or payment provider is connected.</p>${localMerchant().products.filter(p=>!p.quote_only&&p.variants[0].stock>0).slice(0,4).map(p=>`<div class="data-row"><div><strong>${esc(p.name)}</strong><small>${money(p.variants[0].price_cents)} · demo inventory</small></div><button class="button light small" data-action="pos-add" data-product="${p.id}">Add to sale</button></div>`).join('')}<button class="button" style="margin-top:20px" data-action="cart">Open point-of-sale bag</button>`;
 if(state.staffTab==='orders')body=`<h3>Orders & receipts</h3>${d.orders.length?d.orders.map(o=>`<div class="data-row"><div><strong>${esc(o.id)}</strong><small>${new Date(o.created_at).toLocaleString()} · ${esc(o.status)}<br>${o.lines.map(l=>esc(l.name)+' × '+l.quantity).join(', ')}</small></div><strong>${money(o.total_cents)}</strong></div>`).join(''):'<div class="empty">Run a sample sale to see the receipt appear here.</div>'}`;
 if(state.staffTab==='customers'||state.staffTab==='rewards')body=`<h3>${state.staffTab==='customers'?'People, with the context that matters.':'Rewards that stay with the customer.'}</h3><p class="compact-info">Sample rule: earn 1 point per merchandise dollar after reward credit; redeem 100 points for a $5 sample credit. All balances here are fictional.</p>${d.customers.map(c=>`<div class="data-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.email)}</small></div><span class="pill">${c.points} points</span><button class="button light small" data-action="customer" data-customer="${c.id}">Open profile</button></div>`).join('')}`;
 if(state.staffTab==='inventory')body=`<h3>The shelf and the sale, connected.</h3><p class="compact-info">Simulated sales reduce only this merchant’s sample stock. They never alter another business’s inventory.</p>${localMerchant().products.map(p=>`<div class="data-row"><div><strong>${esc(p.name)}</strong><small>${p.variants.map(x=>esc(x.title)+': '+x.stock+' sample units').join(' · ')}</small></div><span>${p.quote_only?'Quote only':money(p.variants[0].price_cents)}</span></div>`).join('')}`;
 if(state.staffTab==='team')body=`<h3>One workspace. Individual sign-ins.</h3><p>${localMode()?'This offline role selector is a simulation. Real team sign-ins require a connection and an active Everbranch membership.':'This session uses your existing Everbranch account. Access to this demo tenant is checked on the server for every staff operation.'}</p><div class="policy-box"><strong>${esc(d.user)}</strong>Current ${localMode()?'sample role':'server-confirmed role'}: ${esc(d.role)}</div>${localMode()?`<label>Demonstrate a role<select id="sample-role"><option ${state.role==='owner'?'selected':''}>owner</option><option ${state.role==='manager'?'selected':''}>manager</option><option ${state.role==='associate'?'selected':''}>associate</option></select></label>`:''}<div class="data-row"><div><strong>Owner / administrator</strong><small>Workspace setup, team access, conversion review and prospect records.</small></div></div><div class="data-row"><div><strong>Manager / associate</strong><small>Assigned demo workspace, sales, customer context and private notes. No prospect sheet or activation access.</small></div></div><p class="compact-info">Real team members use their own provisioned Everbranch email/password account. Memberships and permissions remain server-owned.</p>`;
 openModal(v.name+' · Staff',`<div class="policy-box" style="margin-bottom:20px"><strong>${localMode()?'Offline sample workspace':'Connected demo workspace'}</strong>Fictional people and transactions. No real sale, payment or delivery. <button class="text-button" data-sales-action="voice">Ask AI about this workspace</button></div><div class="staff-layout"><nav class="staff-sidebar" aria-label="Staff sections">${[['overview','In-person sales'],['orders','Orders'],['customers','Customers'],['rewards','Rewards'],['inventory','Inventory'],['team','Team sign-ins']].map(([key,title])=>`<button class="button ${state.staffTab===key?'':'light'}" data-action="staff-tab" data-tab="${key}">${title}</button>`).join('')}${localMode()&&state.role==='owner'?'<button class="text-button" data-action="reset-sample">Reset this sample business</button>':''}</nav><div>${body}</div></div>`,true);state.modal='staff';
}
function customerProfile(id){const c=state.staffData.customers.find(c=>String(c.id)===String(id));if(!c)return;const orders=state.staffData.orders.filter(o=>String(o.customer_id)===String(c.id));openModal(c.name,`<div class="detail-grid"><div><span class="pill">Fictional sample profile</span><p><button class="button light small" data-sales-action="voice" data-voice-customer="${esc(c.id)}">Ask AI about this customer</button></p><h3 style="margin-top:20px">${c.points} reward points</h3><p class="compact-info">${esc(c.email)}</p><h3>Purchase history</h3>${orders.length?orders.map(o=>`<div class="data-row"><div>${esc(o.id)}<small>${esc(o.service)}</small></div><strong>${money(o.total_cents)}</strong></div>`).join(''):'<p class="compact-info">No sample purchases yet.</p>'}<h3 style="margin-top:25px">Reward activity</h3>${(c.reward_entries??[]).map(e=>`<div class="data-row"><div>${esc(e.order_id)}<small>Earned ${e.earned} · redeemed ${e.redeemed}</small></div></div>`).join('')||'<p class="compact-info">Starter demo balance. New sales add reward entries.</p>'}</div><div><h3>Private staff notes</h3><p class="compact-info">Visible only in the staff workspace. Enter sample information, not real customer details.</p>${c.notes.map(n=>`<div class="note"><p>${esc(n.body)}</p><small>${esc(n.by)} · ${new Date(n.at).toLocaleDateString()}</small></div>`).join('')}<form id="customer-note" data-customer="${c.id}"><label>Add a note<textarea name="body" maxlength="2000" required placeholder="Sample: prefers a blue glaze; ask before wrapping as a gift."></textarea></label><button class="button" type="submit">Save private note</button></form></div></div>`);}
async function saveNote(form){const id=form.dataset.customer,body=new FormData(form).get('body').trim();if(!body)return;try{if(localMode()){const data=localData(),c=data.customers.find(c=>String(c.id)===String(id));c.notes.push({body,by:'Sample '+state.role,at:new Date().toISOString()});save('retail-sample-'+merchant().slug,data);}else await api(merchant().slug+'/notes','POST',{customer_id:Number(id),body});await loadStaff();customerProfile(id);toast('Private sample note saved.');}catch(e){toast(e.message);}}
async function openResearch(slug=null){if(state.offline||!state.owner)return toast('Connect with the showroom owner account to open private prospect notes.');try{state.research=(await api('research')).prospects;if(!slug){openModal('Your festival route',`<p class="compact-info">Private salesperson information. Presentation mode excludes this sheet. Stages and notes save to Everbranch’s existing prospect pipeline.</p>${state.research.map(p=>`<div class="data-row"><div><strong>${esc(p.name)}</strong><small>Stop ${p.festival.walking_order??'—'} · ${esc(p.research.booth)} · ${esc(p.festival.stage??'Research')}</small></div><button class="button light small" data-action="lead" data-slug="${p.slug}">Visit & follow up</button></div>`).join('')}`,true);return;}
 const p=state.research.find(p=>p.slug===slug);if(!p)return;const f=p.festival,r=p.research;openModal(p.name+' · Private visit',`<div class="research-grid"><section><div class="eyebrow">${esc(r.booth)} · RESEARCHED 2026-10-15</div><p>${esc(r.web_presence)}</p>${r.site_review?`<div class="policy-box website-review"><strong>Observed website opportunity</strong><p>${esc(r.site_review.observation)}</p>${r.site_review.strengths?.length?`<p class="compact-info">Already working well: ${esc(r.site_review.strengths.join(' · '))}</p>`:''}<p><strong>How Evergrove could help</strong>${esc(r.site_review.opportunity)}</p>${r.site_review.url?`<a class="source-link" href="${esc(r.site_review.url)}" target="_blank" rel="noopener noreferrer">Observed website page ↗</a>`:''}<small>Reviewed ${esc(r.site_review.checked_at??'2026-10-15')} · Private sales research; confirm priorities with the merchant.</small></div>`:''}<h3>A useful conversation</h3><p>${esc(r.concept)}</p><h3>Sources & open questions</h3>${r.sources.map(s=>`<a class="source-link" href="${esc(s)}" target="_blank" rel="noopener noreferrer">${esc(s)}</a>`).join('')}<ul class="checklist">${r.requires_merchant_confirmation.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><div class="form-actions"><button class="button light small" data-action="conversion" data-slug="${slug}">Review customer setup</button><button class="button light small" data-action="share" data-slug="${slug}">Create 24-hour preview link</button><button class="text-button" data-action="revoke" data-slug="${slug}">Revoke preview links</button></div></section><form id="lead-form" data-slug="${slug}"><label>Walking order<input name="walking_order" type="number" min="1" max="99" required value="${f.walking_order??99}"></label><label>Visit stage<select name="stage">${['Research','Visit','Shown','Interested','Proposal','Won','Not interested'].map(s=>`<option ${f.stage===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" name="shown" ${f.shown?'checked':''}> Demonstration shown</label><label>Interest / next step<input name="interest" maxlength="500" value="${esc(f.interest??'')}"></label><label>Contact name voluntarily provided<input name="contact_name" maxlength="160" value="${esc(f.contact_name??'')}"></label><label>Email voluntarily provided<input name="email" type="email" value="${esc(f.email??'')}"></label><label>Follow-up date<input name="follow_up_at" type="date" value="${esc(p.follow_up_at??'')}"></label><label>Private visit notes<textarea name="notes" maxlength="4000">${esc(p.notes??'')}</textarea></label><button class="button" type="submit">Save follow-up</button><p class="compact-info">Saving this record sends no email or text and adds nobody to a campaign.</p></form></div>`,true);}catch(e){toast(e.message);}}
async function saveLead(form){try{const fd=new FormData(form),data=Object.fromEntries(fd);data.shown=fd.has('shown');for(const k of ['email','follow_up_at'])if(!data[k])data[k]=null;await api(form.dataset.slug+'/prospect','PUT',data);toast('Visit and follow-up saved in Everbranch.');closeModal();}catch(e){toast(e.message);}}
function inquiry(){openModal('Start a conversation · sample',`<p>Try a custom order, wholesale, catering or pickup inquiry. This demonstrates the request; it does not contact the merchant.</p><form id="inquiry-form"><label>What would you like to explore?<select name="kind"><option>Custom order</option><option>Wholesale</option><option>Catering / gifting</option><option>Pickup reservation</option></select></label><label>Sample request<textarea name="body" maxlength="1500" required placeholder="Describe a sample request…"></textarea></label><button class="button" type="submit">Save sample inquiry</button></form>`);}
function assortment(){const v=merchant();openModal('Make a little box of happiness.',`<p>Choose two or more flavors for an illustrative gift-box configuration. The price and portion sizes are examples.</p><form id="assortment-form">${v.products.slice(0,5).map(p=>`<label class="check-label"><input type="checkbox" name="flavor" value="${esc(p.name)}">${esc(p.name)}</label>`).join('')}<div class="policy-box" style="margin:20px 0"><strong>Gift-box demo · ${money(v.products[5].variants[0].price_cents)}</strong>Merchant pricing, portion size, packaging, ingredients and shipping need confirmation.</div><button class="button" type="submit">Add my sample box</button></form>`);}
function subscription(){openModal('Your next pantry restock · sample',`<p>Demonstrate repeat ordering without creating a subscription or charging anyone.</p><form id="subscription-form"><label>Choose a favorite<select name="product">${merchant().products.filter(p=>!p.quote_only).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Example reminder cadence<select name="cadence"><option>Every four weeks</option><option>Every six weeks</option><option>Every eight weeks</option></select></label><button class="button" type="submit">Add a sample reorder</button><p class="compact-info">No recurring purchase, message, or billing authorization is created.</p></form>`);}
async function prepareOffline(){if(!state.owner||state.offline)return toast('Connect as the showroom owner to prepare a new offline pack.');try{toast('Saving the showroom and illustrative photographs…');if(!('serviceWorker'in navigator))throw Error('This browser needs a trusted HTTPS connection for offline installation.');await navigator.serviceWorker.register('/retail/sw.js',{scope:'/retail/'});await navigator.serviceWorker.ready;const cache=await caches.open('everbranch-retail-v9');const photoResponse=await fetch('/retail/photos.json',{cache:'reload',credentials:'omit'});if(!photoResponse.ok)throw Error('The demo photo list could not be downloaded.');const photos=await photoResponse.json();if(!Array.isArray(photos)||!photos.length||photos.some(path=>typeof path!=='string'||!/^\/retail\/assets\/[a-z0-9.-]+\.webp$/.test(path)))throw Error('Invalid public demo photo list.');const assets=[...new Set([...photos,...state.pack.vendors.flatMap(v=>['/retail/assets/'+v.image+'.webp',...v.products.filter(p=>p.image?.startsWith('/retail/assets/')).map(p=>p.image)])])];const core=['/retail/offline.html','/retail/app.mjs','/retail/commerce.mjs','/retail/sales.mjs','/retail/voice.mjs','/retail/workbench.mjs','/retail/avery.mjs','/retail/avery-data.mjs','/retail/avery-workspace-data.mjs','/retail/standard-offer.mjs','/retail/app.css','/retail/manifest.webmanifest','/retail/photos.json','/retail/assets/icon.svg','/retail/assets/icon.svg?v=4','/retail/assets/icon-192.png?v=4','/retail/assets/icon-512.png?v=4','/retail/assets/icon-maskable-192.png?v=4','/retail/assets/icon-maskable-512.png?v=4'];await cache.addAll([...core,...assets].map(url=>new Request(url,{cache:'reload',credentials:'omit'})));save('retail-offline-pack',{event:state.pack.event,offer:state.pack.offer,vendors:state.pack.vendors,expires:Date.now()+30*86400000});toast('Offline pack ready. Open each app once before leaving Wi-Fi. Live data and real carrier quotes still need internet.');render();}catch(e){toast('Offline pack could not be completed: '+e.message);}}
function appKit(){openModal('Your Galaxy Tab showroom kit',`<div class="policy-box"><strong>Four apps, one presentation kit.</strong>Retail contains ${state.pack.vendors.filter(v=>v.slug!=='sawyer-naturals').length} festival concepts and the existing Sawyer catalog preview.</div><div class="data-row"><div><strong>Everbranch Retail</strong><small>Chrome menu → Add to home screen → Install. Prepare the offline pack while connected.</small></div><button class="button light small" data-action="offline">Prepare offline pack</button></div><div class="data-row"><div><strong>Everbranch Studio</strong><small>Existing Studio web app. Connect the separate Renfrow book library; Ross’s work remains separate.</small></div><a class="button light small" href="/studio/" target="_blank" rel="noopener">Open Studio</a></div><div class="data-row"><div><strong>Everbranch Field</strong><small>Native Android app: live Collins access and a clearly labeled offline sample business.</small></div></div><div class="data-row"><div><strong>Everbranch Showcase</strong><small>Native Android demo with bundled photographs, films and fictional businesses.</small></div></div><p class="compact-info" style="margin-top:20px">Real team sign-ins, Collins work, cloud syncing and carrier services require a connection. Do not clear browser storage during the festival.</p>`);}
async function boot(){const initial=document.body.dataset.initial||location.pathname.match(/\/(?:concepts|staff|preview)\/([^/]+)/)?.[1]||'';try{const result=await api('bootstrap'+(initial?'?merchant='+encodeURIComponent(initial):''));state.pack=result;state.owner=result.owner;state.staff=result.staff;state.current=initial;}catch(e){const pack=read('retail-offline-pack',null);if((!navigator.onLine||e.offline)&&pack?.expires>Date.now()){state.pack=pack;state.offline=true;state.current=initial;}else{app.innerHTML=`<div class="notice">Everbranch Retail · Private showroom</div><main class="empty"><h1>Your showroom is private.</h1><p>${esc(e.message)}</p><p>Sign in with an authorized account. Offline presentation requires an owner-prepared pack on this device.</p><a class="button" href="/login">Open Everbranch sign-in</a></main>`;return;}}
 render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/retail/sw.js',{scope:'/retail/'}).catch(()=>{});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const action=b.dataset.action,slug=b.dataset.slug;try{
 if(action==='pricing')showSalesView('pricing');
 if(action==='assistant')showSalesView('assistant');
 if(action==='home')navigate(state.pack.vendors.length===1?state.pack.vendors[0].slug:'');
 if(action==='open')navigate(slug);
 if(action==='close')closeModal();
 if(action==='presentation'){closeModal();state.presentation=!state.presentation;render();if(state.presentation)document.documentElement.requestFullscreen?.().catch(()=>{});else if(document.fullscreenElement)document.exitFullscreen?.();}
 if(action==='category'){state.category=b.dataset.category;$('#products').innerHTML=productCards(merchant());document.querySelectorAll('.category').forEach(n=>n.classList.toggle('active',n.dataset.category===state.category));}
 if(action==='product')productDetail(b.dataset.product);
 if(action==='add')await add(b.dataset.product);
 if(action==='pos-add'){await add(b.dataset.product);await loadStaff();openCart();}
 if(action==='cart')openCart();
 if(action==='empty-cart'){await updateCart([]);openCart();}
 if(action==='remove'){await updateCart(cart().filter(l=>!(l.product_id===b.dataset.product&&l.variant_id===b.dataset.variant)));openCart();}
 if(action==='rates')await calculateRates();
 if(action==='checkout')await checkout();
 if(action==='checkout-customers'){if(await loadStaff())openCart();}
 if(action==='staff')await openStaff();
 if(action==='staff-tab'){state.staffTab=b.dataset.tab;renderStaff();}
 if(action==='customer')customerProfile(b.dataset.customer);
 if(action==='shop'||action==='story'){$('#'+(action==='shop'?'catalog':'story'))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
 if(action==='inquiry')inquiry();
 if(action==='assortment')assortment();
 if(action==='subscription')subscription();
 if(action==='offline')await prepareOffline();
 if(action==='kit')appKit();
 if(action==='clear-offline'){localStorage.removeItem('retail-offline-pack');const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('everbranch-retail-')).map(k=>caches.delete(k)));toast('Offline pack removed from this device.');}
 if(action==='reset-sample'){if(!localMode()||state.role!=='owner')throw Error('Only the offline sample owner can reset sample activity.');localStorage.removeItem('retail-sample-'+merchant().slug);localStorage.removeItem('retail-cart-'+merchant().slug);await openStaff();render();toast('This sample business was reset.');}
 if(action==='research-list')await openResearch();
 if(action==='lead')await openResearch(slug);
 if(action==='conversion'){const result=await api(slug+'/conversion');openModal('Customer setup review',`<div class="policy-box"><strong>${esc(result.status)}</strong>This is a saved draft, not an activated customer. Demo orders, customers, users and rewards will not be copied.</div><ul class="checklist">${result.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p>${result.review.products} catalog products are available for review. Live activation remains blocked.</p>`);}
 if(action==='share'){const result=await api(slug+'/share','POST',{});openModal('Private preview link',`<p>Only this storefront is available through this link. It expires ${new Date(result.expires_at).toLocaleString()}. No message was sent.</p><label>Preview URL<input id="preview-url" readonly value="${esc(result.url)}"></label><button class="button" data-action="copy-share">Copy link</button>`);}
 if(action==='copy-share'){await navigator.clipboard.writeText($('#preview-url').value);toast('Preview link copied.');}
 if(action==='revoke'){await api(slug+'/share','DELETE');toast('All preview links for this merchant were revoked.');}
 }catch(error){toast(error.message);}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='merchant-switch')navigate(t.value);if(t.dataset.quantity){const lines=cart();const line=lines.find(l=>l.product_id===t.dataset.quantity&&l.variant_id===t.dataset.variant);line.quantity=Number(t.value);resolveLines(localMerchant(),lines);await updateCart(lines);openCart();}if(t.name==='shipping-service'){state.service=t.value;openCart();}if(t.id==='checkout-customer'){state.customer=t.value;state.redeem=false;openCart();}if(t.id==='redeem-reward'){state.redeem=t.checked;openCart();}if(t.id==='sample-role'){state.role=t.value;await openStaff('team');}if(t.id==='shipping-zip'||t.id==='shipping-state'){state.destination={zip:$('#shipping-zip').value.trim(),state:$('#shipping-state').value};state.rate=null;openCart();}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){state.search=e.target.value;$('#products').innerHTML=productCards(merchant());}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='customer-note')return saveNote(form);if(form.id==='lead-form')return saveLead(form);if(form.id==='inquiry-form'){const data=localData();data.inquiries.push({...Object.fromEntries(new FormData(form)),is_demo:true,created_at:new Date().toISOString()});save('retail-sample-'+merchant().slug,data);closeModal();toast('Sample inquiry saved on this device. No merchant was contacted.');}if(form.id==='assortment-form'){const flavors=new FormData(form).getAll('flavor');if(flavors.length<2)return toast('Choose at least two sample flavors.');save('retail-box-'+merchant().slug,flavors);await add('p6','standard');toast('Sample assortment saved: '+flavors.join(', '));}if(form.id==='subscription-form'){const fd=new FormData(form);await add(fd.get('product'));toast('Sample reorder added. '+fd.get('cadence')+' is an illustration; no subscription was started.');}});
document.addEventListener('keydown',e=>{const modal=$('#modal');if(e.key==='Escape'&&modal)closeModal();if(e.key==='Enter'&&e.target.classList.contains('product-photo')){e.preventDefault();productDetail(e.target.dataset.product);}if(e.key==='Tab'&&modal){const nodes=[...modal.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('popstate',()=>{if(/\/(pricing|assistant)$/.test(location.pathname)){closeModal();state.view=location.pathname.endsWith('/pricing')?'pricing':'assistant';render();}else navigate(location.pathname.match(/\/concepts\/([^/]+)/)?.[1]||'',false);});
window.addEventListener('offline',()=>{state.offline=true;state.owner=false;state.staff=false;state.research=null;state.staffData=null;closeModal();render();toast('Offline sample mode. Live work and private prospect records are unavailable.');});
window.addEventListener('online',()=>{toast('Connection restored. Reload to verify your sign-in before using live tools.');});
sales=createRetailSales({context:()=>({pack:state.pack,owner:state.owner,offline:state.offline,merchant:merchant(),view:state.view,staffTab:state.staffTab,modal:state.modal,voiceSample,averyTool:(name,args)=>avery.voiceTool(name,args),averyContext:()=>avery.voiceContext(),demoTool:(name,args)=>workbench.tool(name,args),demoContext:()=>workbench.snapshot(),demoSelect:slug=>workbench.select(slug),demoInitialize:(slug,records)=>workbench.initialize(slug,records)}),openModal,closeModal,toast,api,navigate:destination=>{if(['customers','rewards','team'].includes(destination)) {if(!merchant())navigate(state.pack.vendors.find(v=>!v.read_only_source).slug);openStaff(destination);}else if(destination==='home')navigate('');else showSalesView(destination);}});
avery=createAvery({context:()=>({merchant:merchant(),offline:state.offline,handoff:()=>api('avery/handoff')}),openModal,toast});
workbench=createDemoWorkbench({context:()=>({merchant:merchant(),vendors:state.pack.vendors,offline:state.offline}),openModal,toast,avery,api});
boot();
